//! 🧪️ Genuine typed-field nulls and comparisons preserve original source custody and one finite bank.
use super::*;
use semio_framework_value_clone_source::RetainedCloneSource;
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
type Pair=(String,String);
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn debit(bank:&mut RetainedCloneGrant,work:u64,p:RetainedCloneProgress,heap:(usize,usize),totals:&mut(usize,usize)){assert!(work<=bank.maximum_items as u64);assert!(p.fits(*bank));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.maximum_items-=work as usize;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;totals.0+=heap.0;totals.1+=heap.1;}
fn source(value:Pair,bank:&mut RetainedCloneGrant,totals:&mut(usize,usize))->RetainedCloneSource<Pair>{
 let mut admission=RetainedCloneSource::<Pair>::admission_owned(value,());let mut output=None;
 for _ in 0..64{
  let ready=admission.phase()=="ready";let d=if ready{RetirementDemand{depth:1,..Default::default()}}else{admission.next_demand().unwrap()};let g=grant(d);
  assert!(g.maximum_items<=bank.maximum_items&&g.maximum_copy_bytes<=bank.maximum_copy_bytes&&g.maximum_capacity_bytes<=bank.maximum_capacity_bytes&&g.maximum_release_bytes<=bank.maximum_release_bytes&&g.maximum_depth<=bank.maximum_depth);
  let(turn,h)=observe(||if ready{admission.take_output(&mut output,g)}else{admission.advance(g)});let work=turn.work;debit(bank,work,turn.result.unwrap().progress(),h,totals);
  if output.is_some(){break}
 }
 assert!(admission.terminal_is_empty());output.unwrap()
}
fn close(source:&mut RetainedCloneSource<Pair>,bank:&mut RetainedCloneGrant,totals:&mut(usize,usize),limit:u64){for _ in 0..limit{if source.terminal_is_empty(){break}let g=grant(source.next_close_demand(4096).unwrap());let(turn,h)=observe(||source.close_step(g));let work=turn.work;debit(bank,work,turn.result.unwrap().progress(),h,totals);}assert!(source.terminal_is_empty());}
#[test]
fn typed_record_actual_null_retry_comparison_and_close_preserve_original_bank(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("actual.schema.json")).unwrap();assert_eq!(schema["properties"]["laws"]["const"],law["laws"]);let limit=law["maximumTurns"].as_u64().unwrap();
 for row in law["cases"].as_array().unwrap(){let stock=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let((left,right),mut totals)=observe(||(serde_json::from_value::<Pair>(row["left"].clone()).unwrap(),serde_json::from_value::<Pair>(row["right"].clone()).unwrap()));let mut left=source(left,&mut bank,&mut totals);let mut right=source(right,&mut bank,&mut totals);let pointers=(left.borrow().get().0.as_ptr(),right.borrow().get().0.as_ptr());let mut owner=RetainedEqualityOwner::<Pair>::new();
 for _ in 0..2{let g=grant(owner.demand(left.borrow(),right.borrow(),4096).unwrap());let(turn,h)=observe(||owner.advance(left.borrow(),right.borrow(),4096,g));let work=turn.work;let step=turn.result.unwrap();assert!(step.equal.is_none());debit(&mut bank,work,step.progress,h,&mut totals);}
 let d=owner.demand(left.borrow(),right.borrow(),4096).unwrap();assert!(d.capacity_bytes>0);let g=grant(d);let(turn,h)=observe(||owner.advance(left.borrow(),right.borrow(),4096,RetainedCloneGrant{maximum_items:0,..g}));assert_eq!(turn.work,law["deniedWork"].as_u64().unwrap());assert!(turn.result.unwrap().equal.is_none());assert_eq!(h,(0,0));let((turn,attempts),h)=observe(||refuse(||owner.advance(left.borrow(),right.borrow(),4096,g)));assert_eq!(attempts,1);assert_eq!(turn.work,law["nullWork"].as_u64().unwrap());let work=turn.work;let error=turn.result.err().unwrap();debit(&mut bank,work,error.retained_progress(),h,&mut totals);assert_eq!(owner.result(),None);assert_eq!(left.borrow().get().0.as_ptr(),pointers.0);assert_eq!(right.borrow().get().0.as_ptr(),pointers.1);
 for _ in 0..limit{if owner.result().is_some(){break}let g=grant(owner.demand(left.borrow(),right.borrow(),4096).unwrap());let(turn,h)=observe(||owner.advance(left.borrow(),right.borrow(),4096,g));let work=turn.work;debit(&mut bank,work,turn.result.unwrap().progress,h,&mut totals);}assert_eq!(owner.result(),Some(row["left"]==row["right"]));let(turn,h)=observe(||owner.advance(left.borrow(),right.borrow(),4096,Default::default()));assert_eq!(turn.work,law["cachedWork"].as_u64().unwrap());assert_eq!(turn.result.unwrap().progress,Default::default());assert_eq!(h,(0,0));owner.begin_close();for _ in 0..limit{if owner.terminal_is_empty(){break}let g=grant(owner.close_demand(4096).unwrap());let(turn,h)=observe(||owner.close_step(g));let work=turn.work;debit(&mut bank,work,turn.result.unwrap().progress(),h,&mut totals);}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));close(&mut left,&mut bank,&mut totals,limit);close(&mut right,&mut bank,&mut totals,limit);assert_eq!(observe(||drop((left,right))).1,(0,0));assert_eq!(totals.0,totals.1);}
}

#[test]
fn compound_zero_sized_equality_cannot_collapse_a_large_input_into_one_paid_probe(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();assert_eq!(law["compoundTraversal"]["zeroArrayLength"],4097);type Value=Option<[();4097]>;let left=Some([();4097]);let right=Some([();4097]);assert_eq!(left,right);let mut cursor=Value::equality_cursor();let stock=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let mut totals=(0,0);
 while bank.maximum_items>law["compoundTraversal"]["reserveCloseItems"].as_u64().unwrap()as usize{let g=grant(RetainedEqualityCursor::<Option<[();4097]>>::demand(&cursor,&left,&right,4096).unwrap());let(turn,h)=observe(||RetainedEqualityCursor::<Option<[();4097]>>::advance(&mut cursor,&left,&right,g));let work=turn.work;assert_eq!(work,1);let step=turn.result.unwrap();assert!(step.equal.is_none());debit(&mut bank,work,step.progress,h,&mut totals);}
 let d=RetainedEqualityCursor::<Option<[();4097]>>::demand(&cursor,&left,&right,4096).unwrap();let(turn,h)=observe(||RetainedEqualityCursor::<Option<[();4097]>>::advance(&mut cursor,&left,&right,RetainedCloneGrant{maximum_items:0,..grant(d)}));assert_eq!(turn.work,0);let step=turn.result.unwrap();assert!(step.equal.is_none());assert_eq!(step.progress,Default::default());assert_eq!(h,(0,0));cursor.begin_close();let g=grant(cursor.close_demand(4096).unwrap());let(turn,h)=observe(||cursor.close_step(g));let work=turn.work;debit(&mut bank,work,turn.result.unwrap().progress(),h,&mut totals);assert!(cursor.terminal_is_empty());assert_eq!(observe(||drop(cursor)).1,(0,0));assert_eq!(totals.0,totals.1);
}
